import itertools, numpy as np
S={(0,1),(1,0),(1,2)}
cells=[(r,c) for r in range(3) for c in range(3) if (r,c) not in S]
def syms(A):
 return [name for name,B in [('v',{(r,2-c) for r,c in A}),('h',{(2-r,c) for r,c in A}),('main',{(c,r) for r,c in A}),('anti',{(2-c,2-r) for r,c in A})] if B==A]
for add in itertools.combinations(cells,2):
 A=S|set(add)
 if syms(A):
  print(add,syms(A));print(np.array([[int((r,c) in A) for c in range(3)] for r in range(3)]))
